// Host tests for copperui/pack.h (no Qt, no C++ standard library).
// Run: make -C lib/copperui docker-test (or make -C mod/drawer docker-test)

#include "copperui/pack.h"
#include "test_expect.h"

using namespace copperui::v1;

struct PackVector {
    const char *name;
    int available;
    int blockCount;
    int blocks[12][3]; // height, gap, keepWithNext
    int pages[12];
};

#include "pack_vectors.inc" // generated by `make tokens`

static void testSharedVectors()
{
    for (unsigned i = 0; i < sizeof(PACK_VECTORS) / sizeof(PACK_VECTORS[0]); i++) {
        const PackVector &vector = PACK_VECTORS[i];
        Block blocks[MAX_PACK_BLOCKS];
        int pages[MAX_PACK_BLOCKS + 1];
        int expectedCount = 1;
        for (int b = 0; b < vector.blockCount; b++) {
            blocks[b].height = vector.blocks[b][0];
            blocks[b].gap = vector.blocks[b][1];
            blocks[b].keepWithNext = vector.blocks[b][2] != 0;
            expectedCount = vector.pages[b] + 1 > expectedCount ? vector.pages[b] + 1 : expectedCount;
        }
        int count = packPages(blocks, vector.blockCount, vector.available, pages);
        if (count != expectedCount) {
            printf("vector \"%s\": %d page(s), expected %d\n", vector.name, count, expectedCount);
            failures++;
        }
        for (int b = 0; b < vector.blockCount; b++) {
            if (pages[b] != vector.pages[b]) {
                printf("vector \"%s\": block %d on page %d, expected %d\n", vector.name, b, pages[b], vector.pages[b]);
                failures++;
            }
        }
    }
}

static void testBlocksHeightLeavesOutTheLastGap()
{
    Block blocks[] = {{100, 10, false}, {200, 24, false}, {50, 99, false}};
    EXPECT_EQ(100 + 10 + 200 + 24 + 50, blocksHeight(blocks, 0, 3));
    EXPECT_EQ(200, blocksHeight(blocks, 1, 1));
    EXPECT_EQ(0, blocksHeight(blocks, 1, 0));
}

static void testBodyFrameAddsThePagerOnlyForMorePages()
{
    Block body[12];
    int pages[13];
    for (int i = 0; i < 12; i++) {
        body[i].height = 104;
        body[i].gap = 0;
        body[i].keepWithNext = false;
    }
    BodyFrame frame = layoutBody(body, 3, 120, PAGE_HEIGHT, pages);
    EXPECT_EQ(1, frame.pageCount);
    EXPECT_EQ(HEADER_HEIGHT + RHYTHM, frame.top);
    EXPECT_EQ(PAGE_HEIGHT - MARGIN_BOTTOM - 120, frame.footerTop);
    EXPECT_EQ(frame.footerTop - RHYTHM, frame.bottom);
    frame = layoutBody(body, 12, 120, PAGE_HEIGHT, pages);
    EXPECT_EQ(2, frame.pageCount);
    EXPECT_EQ(frame.bottom - PAGER_HEIGHT, frame.pageBarTop);
    // The pager takes room from every page: the first page holds fewer rows than without it.
    int onFirstPage = 0;
    for (int i = 0; i < 12; i++) {
        onFirstPage += pages[i] == 0 ? 1 : 0;
    }
    EXPECT_EQ((frame.bottom - frame.top - PAGER_HEIGHT - RHYTHM) / 104, onFirstPage);
}

int main()
{
    testSharedVectors();
    testBlocksHeightLeavesOutTheLastGap();
    testBodyFrameAddsThePagerOnlyForMorePages();
    return finishTests("copperui pack");
}
